+// file COPYING or http://www.opensource.org/licenses/mit-license.php.
+
+#include <addresstype.h>
+#include <common/bip352.h>
+#include <optional>
+#include <primitives/transaction.h>
+#include <secp256k1_extrakeys.h>
+#include <pubkey.h>
