+        recipient_ptrs.data(), recipient_ptrs.size(),
+        smallest_outpoint_ser.data(),
+        taproot_keypair_ptrs.data(), taproot_keypair_ptrs.size(),
+        plain_key_ptrs.data(), plain_key_ptrs.size()
+    );
+    if (!ret) return {};
+    return generated_outputs;
+}
