+    }
+    for (const auto& key : plain_keys) {
+        plain_key_ptrs.push_back(UCharCast(key.begin()));
+    }
+    for (const auto& keypair : taproot_keypairs) {
+        taproot_keypair_ptrs.push_back(reinterpret_cast<const secp256k1_keypair*>(keypair.data()));
+    }
